/** Fresh isolated profiles; captures real render geometry and physical button effects, never sends the draft. */
@Mod.EventBusSubscriber(modid=DisCraft.ID,value=Dist.CLIENT)
public final class PendingCardAcceptance {
 private static final Minecraft MC=Minecraft.getInstance();private static final boolean CP=Boolean.getBoolean("discraft.chatPlusSmoke");
 private static int phase,ticks,profile,eventX,eventY,baselineX,baselineY;private static int[] inputAtInit,baselineInput;private static boolean done;private static String caption="";
 private static boolean lowResized;private static PendingCardLayout.Rect staleRemove;
 private static CountDownLatch slowGate;private static List<Object> configBefore;private static final List<String> checks=new ArrayList<>();private static Set<UUID> before;private static Robot robot;private static ExecutorService mouse;private static Future<?> action;
 private static boolean enabled(){return Boolean.getBoolean("discraft.pendingCardSmoke");}private static Path out(){return Path.of(System.getProperty("discraft.twemojiOutput"));}
 private static String profileLabel(){return profile==3?"Low-height CP":profile==0?"Default":profile==1?"Narrow":CP?"Moved CP":"Scale stress";}
 private static String name(){return (CP?"chatplus":"vanilla")+"-"+(profile==0?"default":profile==1?"narrow":profile==3?"low-height":"stress");}
 private static Object get(Class<?> type,String name)throws Exception{var f=type.getDeclaredField(name);f.setAccessible(true);return f.get(null);}
 private static Object invoke(Class<?> type,String name)throws Exception{var m=type.getDeclaredMethod(name);m.setAccessible(true);return m.invoke(null);}
 private static Object getter(Object object,String name)throws Exception{return object.getClass().getMethod(name).invoke(object);}
 private static EditBox input(){return ObfuscationReflectionHelper.getPrivateValue(ChatScreen.class,(ChatScreen)MC.screen,"f_95573_");}
 private static List<?> windows()throws Exception{return (List<?>)getter(getter(ChatPlusAcceptance.singleton("config.Config"),"getValues"),"getChatWindows");}
 private static List<Object> config()throws Exception{var settings=getter(getter(ChatPlusAcceptance.singleton("config.Config"),"getValues"),"getInputBoxSettings");var values=new ArrayList<Object>();for(String k:List.of("getStartX","getStartY","getWidth"))values.add(getter(settings,k));for(var w:windows()){var r=getter(w,"getRenderer");for(String k:List.of("getX","getY","getWidth","getHeight"))values.add(getter(r,k));var g=getter(w,"getGeneralSettings");for(String k:List.of("getScale","getLineSpacing"))values.add(getter(g,k));}return List.copyOf(values);}
 private static int[] origin()throws Exception{if(!CP)return new int[]{eventX,eventY};var r=getter(windows().get(0),"getRenderer");return new int[]{((Number)getter(r,"getInternalX")).intValue(),((Number)getter(r,"getInternalY")).intValue()};}
 private static Set<UUID> owned(){var ids=new HashSet<UUID>();for(var m:ClientBridge.snapshot())if(m.author().equals(MC.player.getGameProfile().getName()))ids.add(m.id());return ids;}
 private static void check(boolean value,String label){if(!value)throw new AssertionError(label);checks.add("PASS "+label);System.out.println("PENDING_CARD PASS "+label);}
 private static void next(int value){phase=value;ticks=0;}
 private static void capture(String suffix)throws Exception{try(var image=Screenshot.takeScreenshot(MC.getMainRenderTarget())){check(image.getWidth()==(profile==3&&lowResized?960:profile==1?960:1280)&&image.getHeight()==(profile==1?720:900),"Original framebuffer "+name()+"-"+suffix);image.writeToFile(out().resolve(name()+"-"+suffix+".png"));}}
 private static PendingCardLayout.Placement placement()throws Exception{return (PendingCardLayout.Placement)get(NativeInteractions.class,"displayedCard");}
 private static boolean ready()throws Exception{return Boolean.TRUE.equals(invoke(NativeInteractions.class,"currentCard"));}
 private static PendingCardLayout.Placement controls()throws Exception{if(!ready())return null;var p=placement();if(p.mode()==PendingCardLayout.Mode.HIDDEN){if(!(Boolean)get(NativeInteractions.class,"open")){NativeInteractions.openPicker();return null;}return (PendingCardLayout.Placement)invoke(NativeInteractions.class,"footer");}return p;}
 private static void move(PendingCardLayout.Rect r,boolean click){GLFW.glfwFocusWindow(MC.getWindow().getWindow());int[] x={0},y={0};GLFW.glfwGetWindowPos(MC.getWindow().getWindow(),x,y);double scale=MC.getWindow().getGuiScale();int px=x[0]+(int)((r.x()+r.width()/2d)*scale),py=y[0]+(int)((r.y()+r.height()/2d)*scale);action=mouse.submit(()->{robot.mouseMove(px,py);if(click){robot.mousePress(InputEvent.BUTTON1_DOWN_MASK);robot.delay(60);robot.mouseRelease(InputEvent.BUTTON1_DOWN_MASK);}});}
 private static void profile()throws Exception{invoke(NativeInteractions.class,"closePicker");MC.options.guiScale().set(profile==0?2:3);MC.options.chatScale().set(profile==2&&!CP?.6d:1d);GLFW.glfwSetWindowSize(MC.getWindow().getWindow(),profile==1?960:1280,profile==1?720:900);GLFW.glfwSetWindowPos(MC.getWindow().getWindow(),0,0);MC.resizeDisplay();if(CP&&profile>=2){ChatPlusAcceptance.configure(1);for(var w:windows()){var r=getter(w,"getRenderer");r.getClass().getMethod("setHeight",int.class).invoke(r,MC.getWindow().getGuiScaledHeight()-24);r.getClass().getMethod("updateCachedDimension").invoke(r);}}if(CP&&profile==3){
   var settings=getter(getter(ChatPlusAcceptance.singleton("config.Config"),"getValues"),"getInputBoxSettings");settings.getClass().getMethod("setStartY",int.class).invoke(settings,146);
   for(var w:windows()){var r=getter(w,"getRenderer");var general=getter(w,"getGeneralSettings");general.getClass().getMethod("setScale",float.class).invoke(general,1f);for(var setting:Map.of("setX",0,"setY",300,"setWidth",MC.getWindow().getGuiScaledWidth(),"setHeight",300).entrySet())r.getClass().getMethod(setting.getKey(),int.class).invoke(r,setting.getValue());r.getClass().getMethod("updateCachedDimension").invoke(r);}
  }MC.setScreen(new ChatScreen("draft retained — not sent"));caption=profileLabel()+" | No pending";next(3);}
 @SubscribeEvent(priority=EventPriority.HIGHEST)public static void init(ScreenEvent.Init.Post e){if(enabled()&&e.getScreen() instanceof ChatScreen){var box=ObfuscationReflectionHelper.<EditBox,ChatScreen>getPrivateValue(ChatScreen.class,(ChatScreen)e.getScreen(),"f_95573_");inputAtInit=new int[]{box.getX(),box.getY()};}}
 @SubscribeEvent(priority=EventPriority.LOWEST)public static void position(CustomizeGuiOverlayEvent.Chat e){if(enabled()){eventX=e.getPosX();eventY=e.getPosY();}}
 @SubscribeEvent(priority=EventPriority.LOWEST)public static void label(ScreenEvent.Render.Post e){if(!enabled()||!(e.getScreen() instanceof ChatScreen))return;var g=e.getGuiGraphics();int width=Math.max(100,Math.min(280,e.getScreen().width/2-8));g.fill(4,4,4+width,49,0xe0000000);g.drawString(MC.font,MC.font.plainSubstrByWidth("TEST ONLY | "+(CP?"ChatPlus":"Vanilla"),width-10),9,9,0xffffd36b,false);g.drawString(MC.font,MC.font.plainSubstrByWidth(caption,width-10),9,22,0xffeeeeee,false);g.drawString(MC.font,"No Discord send.",9,35,0xffcccccc,false);}
 @SubscribeEvent public static void tick(TickEvent.ClientTickEvent e){if(!enabled()||done||e.phase!=TickEvent.Phase.END)return;try{if(action!=null){if(!action.isDone())return;action.get();action=null;}ticks++;if(phase>=3&&ticks>400)throw new AssertionError("Pending-card phase stalled: "+phase+" profile="+profile);MC.getToasts().clear();switch(phase){
 case 0->{if(MC.screen instanceof AccessibilityOnboardingScreen){MC.screen.children().stream().filter(c->c instanceof Button b&&b.getMessage().getString().equals("Continue")).map(c->(Button)c).findFirst().ifPresent(Button::onPress);return;}if(!(MC.screen instanceof TitleScreen)||MC.getOverlay()!=null)return;Files.createDirectories(out());check(net.minecraftforge.fml.ModList.get().isLoaded("chatplus")==CP,"Actual fixture loads the requested vanilla or ChatPlus renderer");MC.options.guiScale().set(2);MC.options.renderDistance().set(2);MC.options.chatWidth().set(1d);MC.options.chatHeightFocused().set(1d);MC.options.chatLineSpacing().set(0d);MC.resizeDisplay();robot=new Robot();mouse=Executors.newSingleThreadExecutor(r->{var t=new Thread(r,"Pending-card physical mouse");t.setDaemon(true);return t;});String address="127.0.0.1:"+System.getProperty("discraft.bridgePort");ConnectScreen.startConnecting(new TitleScreen(),MC,ServerAddress.parseString(address),new ServerData("Pending card LOCAL TEST",address,false),false);next(1);}
 case 1->{if(MC.player==null||MC.level==null||MC.screen!=null||!ClientBridge.available()||ticks<25)return;MC.gui.getChat().clearMessages(false);NativeChat.reset();if(CP)for(var w:windows())for(var t:(List<?>)getter(getter(w,"getTabSettings"),"getTabs"))t.getClass().getMethod("clear").invoke(t);MC.player.connection.sendChat("Normal chat remains in place.");before=owned();profile();}
 case 3->{if(ticks<25)return;check(input().getX()==inputAtInit[0]&&input().getY()==inputAtInit[1],"DisCraft leaves vanilla/upstream input x/y unchanged for "+name());baselineInput=new int[]{input().getX(),input().getY(),input().getWidth(),input().getHeight()};var o=origin();baselineX=o[0];baselineY=o[1];if(CP){configBefore=config();if(profile==0)check(configBefore.get(0).equals(2)&&configBefore.get(1).equals(-10),"Normal ChatPlus proof starts from fresh upstream defaults, not a moved fixture");}else if(profile==0)check(input().getX()==4&&input().getY()==MC.screen.height-12,"Normal native proof uses the pinned bottom input position");capture("no-pending");var stage=NativeComposer.class.getDeclaredMethod("stage",Callable.class);stage.setAccessible(true);stage.invoke(null,(Callable<Attachment>)()->Attachment.of("sample.png",Attachment.fromResource("landscape.png").bytes()));caption=profileLabel()+" | Preparing image";next(4);}
 case 4->{if(ticks<15||invoke(NativeComposer.class,"selected")==null||(Boolean)invoke(NativeComposer.class,"validating")||!ready())return;check(input().getX()==baselineInput[0]&&input().getY()==baselineInput[1]&&input().getWidth()==baselineInput[2]&&input().getHeight()==baselineInput[3]&&Arrays.equals(origin(),new int[]{baselineX,baselineY}),"Pending image moves neither input nor history anchor for "+name());if(CP)check(config().equals(configBefore),"Pending layout does not write ChatPlus position or scale settings for "+name());var p=placement();check(p.mode()==PendingCardLayout.Mode.HIDDEN||p.bounds().x()>=MC.screen.width/2,"Pending card stays on right or safely hides for "+name());if(profile==3)check(MC.screen.height==300&&input().getY()==146&&p.mode()==PendingCardLayout.Mode.HIDDEN&&((PendingCardLayout.Rect)invoke(NativeInteractions.class,"picker")).height()<144,"Exact low-height ChatPlus input and full-right history reproduce hidden card with unavailable full picker");if(profile==0)check(p.mode()==PendingCardLayout.Mode.FULL,"Normal default layout has an actual right-side preview");if(!CP&&profile==1)check(p.mode()==PendingCardLayout.Mode.HIDDEN,"Full-width narrow native chat safely hides the preview instead of covering history");caption=profileLabel()+(p.mode()==PendingCardLayout.Mode.HIDDEN?" | Hidden preview":p.mode()==PendingCardLayout.Mode.COMPACT?" | Filename only":" | Right preview");capture("pending");if(p.mode()==PendingCardLayout.Mode.HIDDEN){var button=(AbstractWidget)get(NativeInteractions.class,"smiley");move(new PendingCardLayout.Rect(button.getX(),button.getY(),18,16),false);next(40);return;}NativeInteractions.openPicker();caption=profileLabel()+" | Picker";next(5);}
 case 40->{if(ticks<6)return;capture("fallback-hint");if(profile==3){var button=(AbstractWidget)get(NativeInteractions.class,"smiley");move(new PendingCardLayout.Rect(button.getX(),button.getY(),18,16),true);}else NativeInteractions.openPicker();caption=profileLabel()+" | Picker";next(5);}
 case 5->{if(ticks<12||!ready())return;if(profile==3)check((Boolean)get(NativeInteractions.class,"open")&&(Boolean)invoke(NativeInteractions.class,"compact")&&!((EditBox)get(NativeInteractions.class,"search")).visible,"Physical smiley click opens low-height attachment controls without a full picker/search");if(profile==3){var box=(PendingCardLayout.Rect)invoke(NativeInteractions.class,"picker");var wheel=new ScreenEvent.MouseScrolled.Pre(MC.screen,box.x()+10,box.y()+8,-1);NativeInteractions.scroll(wheel);check(!wheel.isCanceled(),"Compact manager does not consume history scrolling in the undrawn full-picker area");}capture("picker");var p=controls();if(p==null)return;move(p.spoiler(),false);next(6);}
 case 6->{if(ticks<6)return;capture("spoiler-hover");var p=controls();if(p==null)return;move(p.spoiler(),true);next(7);}
 case 7->{if(ticks<6)return;check((Boolean)invoke(NativeComposer.class,"isSpoiler")&&!(Boolean)invoke(NativeComposer.class,"previewVisible"),"Physical right-side/fallback spoiler click hides the pending image without send for "+name());var p=controls();if(p==null)return;if(profile==3&&!lowResized){staleRemove=p.remove();GLFW.glfwSetWindowSize(MC.getWindow().getWindow(),960,900);MC.resizeDisplay();lowResized=true;check(!(Boolean)invoke(NativeInteractions.class,"currentFooter"),"Resize immediately invalidates previously drawn attachment control geometry");next(71);return;}move(p.remove(),false);next(8);}
 case 71->{if(ticks<12)return;if(!(Boolean)get(NativeInteractions.class,"open")){var button=(AbstractWidget)get(NativeInteractions.class,"smiley");move(new PendingCardLayout.Rect(button.getX(),button.getY(),18,16),true);next(72);return;}next(72);}
 case 72->{if(ticks<8)return;var p=controls();if(p==null)return;check(!p.remove().equals(staleRemove),"Resized low-height manager moves hitbox: old="+staleRemove+" new="+p.remove());check(input().getX()==inputAtInit[0]&&input().getY()==inputAtInit[1],"Resized input remains upstream-owned: actual="+input().getX()+","+input().getY()+" init="+Arrays.toString(inputAtInit));capture("resized-manager");move(staleRemove,true);next(73);}
 case 73->{if(ticks<8)return;check(invoke(NativeComposer.class,"selected")!=null&&(Boolean)invoke(NativeComposer.class,"isSpoiler")&&input().getValue().equals("draft retained — not sent"),"Physical stale-location click after resize cannot remove staged media or change draft");var p=controls();if(p==null)return;move(p.remove(),false);next(8);}
 case 8->{if(ticks<6)return;capture("remove-hover");var p=controls();if(p==null)return;move(p.remove(),true);next(9);}
 case 9->{if(ticks<8||invoke(NativeComposer.class,"selected")!=null)return;check(get(NativeInteractions.class,"displayedAttachment")==null,"Removed pending image releases its rendered attachment reference for "+name());check(owned().equals(before)&&input().getValue().equals("draft retained — not sent")&&Arrays.equals(origin(),new int[]{baselineX,baselineY}),"Physical remove keeps draft/history and never sends for "+name());invoke(NativeInteractions.class,"closePicker");if(++profile<(CP?4:3)){profile();return;}profile=CP?3:2;slowGate=new CountDownLatch(1);var stage=NativeComposer.class.getDeclaredMethod("stage",Callable.class);stage.setAccessible(true);stage.invoke(null,(Callable<Attachment>)()->{while(slowGate.getCount()>0)try{slowGate.await(100,TimeUnit.MILLISECONDS);}catch(InterruptedException ignored){}return Attachment.of("late.png",Attachment.fromResource("landscape.png").bytes());});caption=profileLabel()+" | Cancel validation";next(10);}
 case 10->{if(ticks<10||!(Boolean)invoke(NativeComposer.class,"validating"))return;var p=controls();if(p==null)return;check(invoke(NativeComposer.class,"selected")==null,"Pending validation has no decoded image before physical cancellation");move(p.remove(),true);next(11);}
 case 11->{if(ticks<6)return;check(!(Boolean)invoke(NativeComposer.class,"validating")&&invoke(NativeComposer.class,"selected")==null,"Physical pending remove cancels in-flight validation");slowGate.countDown();next(12);}
 case 12->{if(ticks<12)return;check(invoke(NativeComposer.class,"selected")==null&&get(NativeInteractions.class,"displayedAttachment")==null&&owned().equals(before)&&Arrays.equals(origin(),new int[]{baselineX,baselineY}),"Late cancelled decoder cannot restore a card, move history or send");checks.add("PASS "+checks.size()+" actual pending-card profile/anchor/physical-control checks; local TEST only");Files.write(out().resolve("result.txt"),checks);mouse.shutdownNow();MC.level.disconnect();MC.clearLevel();done=true;MC.stop();}
 }}catch(Throwable failure){if(slowGate!=null)slowGate.countDown();try{checks.add("FAIL phase="+phase+" profile="+profile+" "+failure.getClass().getSimpleName()+": "+failure.getMessage());Files.write(out().resolve("result.txt"),checks);}catch(Exception ignored){}if(mouse!=null)mouse.shutdownNow();done=true;MC.stop();}}
}
